window.MARGHERA_IMG={"accovacciato": "data:image/png;base64,", "aterra": "data:image/png;base64,", "boom": "data:image/png;base64,", "calcio": "data:image/png;base64,", "camminata1": "data:image/png;base64,", "camminata2": "data:image/png;base64,", "cicogna1": "data:image/png;base64,", "cicogna2": "data:image/png;base64,", "ciuccio": "data:image/png;base64,", "colpito": "data:image/png;base64,", "evoca": "data:image/png;base64,", "fagotto": "data:image/png;base64,", "gatto_corsa1": "data:image/png;base64,", "gatto_corsa2": "data:image/png;base64,", "gatto_salto": "data:image/png;base64,", "gatto_seduta": "data:image/png;base64,", "gattob_corsa1": "data:image/png;base64,", "gattob_corsa2": "data:image/png;base64,", "gattob_salto": "data:image/png;base64,", "gattob_seduta": "data:image/png;base64,", "guardia": "data:image/png;base64,", "ko": "data:image/png;base64,", "lancio": "data:image/png;base64,", "montante": "data:image/png;base64,", "onda": "data:image/png;base64,", "parata": "data:image/png;base64,", "provocazione": "data:image/png;base64,", "pugno": "data:image/png;base64,", "rialzo": "data:image/png;base64,", "ritratto": "data:image/png;base64,", "salto": "data:image/png;base64,", "sconfitta": "data:image/png;base64,", "sgambetto": "data:image/png;base64,", "stordito": "data:image/png;base64,", "super1": "data:image/png;base64,", "testa": "data:image/png;base64,", "tifo": "data:image/png;base64,", "tigre": "data:image/png;base64,", "vittoria": "data:image/png;base64,"};window.MARGHERA_SCR={"CIUCCIO": "data:image/png;base64,", "CONSEGNA": "data:image/png;base64,", "PARRRTO": "data:image/png;base64,", "RRRESPIRA": "data:image/png;base64,", "RRROAR": "data:image/png;base64,"};window.MARGHERA_SRC="\nQUOTES.marghera={intro:[\"Rrrespira. Adesso spingi.\",\"Odino, Furio: in posizione.\",\"Tranquillo, ho fatto nascere di peggio.\",\"Turno di notte finito. Tocca a te.\"],win:[\"Parrrto riuscito.\",\"Tre chili e due. Di sconfitta.\",\"Odino, Furio: si torna a casa.\",\"Prrrossimo!\"],lose:[\"Contrazioni... false.\",\"Domani rrrivincita. Dopo il turno.\",\"Odino... Furio... coccole.\"]};\nCOUPLE.marghera=COUPLE.marghera||{};\nCOUPLE.marghera.carolluz={intro:[\"Carolluz, cambio turno. Ti do il cambio io.\"],win:[\"Sala parto mia, collega.\"],lose:[\"Va bene, il prossimo lo fai nascere tu.\"]};\nCOUPLE.carolluz=COUPLE.carolluz||{}; COUPLE.carolluz.marghera={intro:[\"Marghera, l'hai letto il regolamento?\"],win:[\"Te l'avevo detto.\"],lose:[\"Va bene, offri tu lo spritz.\"]};\nCOUPLE.marghera.marouges={intro:[\"Marouges, niente blasfemie in sala parto.\"],win:[\"Rrrespira, collega.\"],lose:[\"Va bene, BOING. Hai vinto.\"]};\nCOUPLE.marouges=COUPLE.marouges||{}; COUPLE.marouges.marghera={intro:[\"Marghera, oggi non ho pazienza.\"],win:[\"Turno chiuso.\"],lose:[\"Odino e Furio barano.\"]};\nCOUPLE.marghera.nicozago={intro:[\"Nico, apri il caveau. Arrivano i gatti.\"],win:[\"Interessi pagati.\"],lose:[\"Va bene, direttore.\"]};\nCOUPLE.marghera.stefano={intro:[\"SDB, i tuoi gatti contro i miei?\"],win:[\"Odino e Furio: due a zero.\"],lose:[\"Avvocato, mi appello.\"]};\nCOUPLE.stefano=COUPLE.stefano||{}; COUPLE.stefano.marghera={intro:[\"Marghera, obiezione: i gatti non valgono.\"],win:[\"Respinta. Con le spese.\"],lose:[\"Boogie e Mocambo, consolatemi.\"]};\nCOUPLE.marghera.jj={intro:[\"JJ, sorridi. Fa bene.\"],win:[\"Visto? Un sorriso.\"],lose:[\"Va bene, niente sorrisi.\"]};\nif(SPRITES.marghera){ const N=SPRITES.marghera; N.guardia2=N.guardia; N.paratabassa=N.accovacciato; N.entrata=N.provocazione; N.lancio2=N.lancio; N.caricacalcio=N.guardia; N.caricapugno=N.guardia; N.sguardo=N.provocazione; N.turbo=N.pugno; N.sfondamento=N.pugno; N.stordita=N.stordito; N.super2=N.super1; N.esulta1=N.vittoria; N.esulta2=N.tifo; N.esulta3=N.vittoria; N.volo=N.ko; N.svenuto0=N.aterra; N.vittoria2=N.vittoria; N.vittoria3=N.vittoria; if(!N.presa) N.presa=N.pugno; if(!N.rialzo) N.rialzo=N.accovacciato; }\n/* MARGHERA1 - base: ciuccio lanciato (distanza), Odino e Furio (speciale: i due gatti grigi corrono e saltano), super \"Cicogna express\" (la cicogna lascia cadere il fagotto).\n   Evoluzione OSTETRICA (capelli argento, aura bianca): distanza ciuccio, speciale ruggito (piccola onda bianca), super \"Spirito della tigre\": la tigre siberiana appare e parte l'onda di energia bianca. */\nfunction margImg(n){ const D=window.MARGHERA_IMG||{}, c=SPRITES.__mImg=SPRITES.__mImg||{}; if(!D[n]) return null; if(!c[n]){ const i=new Image(); i.src=D[n]; c[n]=i; } return c[n].complete&&c[n].width?c[n]:null; }\nfunction drawMargProj(p){ let im, s=1, rot=0;\n  if(p.kind==='ciuccio'){ im=margImg('ciuccio'); s=1; rot=(G.frame%30)/30*Math.PI*2*(p.vx<0?-1:1); }\n  else if(p.mruggito){ im=margImg('testa'); s=0.95+0.07*Math.sin(G.frame*0.6); }\n  if(!im) return false; ctx.save(); ctx.translate(p.x,p.y); ctx.scale(p.vx<0?-1:1,1); if(rot) ctx.rotate(rot); ctx.imageSmoothingEnabled=false; ctx.drawImage(im,-im.width*s/2,-im.height*s/2,im.width*s,im.height*s); ctx.restore(); return true; }\nconst MARGSU={dmg:17,dmgE:18,vel:13,rng:80,wv:15}; try{ setTimeout(()=>['ciuccio','cicogna1','cicogna2','fagotto','tigre','onda','boom','testa'].forEach(margImg),0); }catch(e){}\nwindow.__margCatImg=function(p){ const M=SPRITES.marghera||{}, fz=((p.r*1.4|0)%2)+1, pre=p.brown?'gatto_':'gattob_';\n  const k=p.mode==='off'?pre+'seduta':(p.mode==='leap'?pre+'salto':pre+'corsa'+fz); const im=M[k]||M['gatto_'+k.slice(pre.length)]; return (im&&im.complete&&im.width)?im:null; };\nfunction callMargGatti(f,o){ const d=f.facing||1; floatText('Odino! Furio!',f.x,f.y-250,f.def.accent,17,46,'balloon');\n  [[1,0],[0,9]].forEach(([scuro,delay],i)=>{ const x=Math.max(30,Math.min(W-30,f.x-d*(40+i*36))); P.push({o:f,kind:'cat',fan:1,sep:1,marg:1,slot:95+i,brown:scuro,mode:'wait',t:-delay,x,y:GROUND-2,hx:x,hy:GROUND-2,vx:0,vy:0,dir:d,dmg:11,r:0,sup:true,tgt:o}); }); }\nfunction callMargCicogna(f,o){ const dir=f.facing||1; f.mgsup={t:0,dir,cx:dir>0?-90:W+90,tgt:o,hit:0,drop:null,sp:1}; floatText('Cicogna!',f.x,f.y-250,f.def.accent,17,46,'balloon'); try{ tone('triangle',700,900,.4,.06); }catch(e){} }\nfunction callMarg(f,o){ const dir=f.facing||1;\n  if(f.def.lv>=2){ f.mgsup={t:0,evo:1,dir,wx:f.x,tgt:o,hit:0}; floatText('RRRESPIRA!',f.x,f.y-270,'#ffffff',26,60); try{ tone('sawtooth',80,40,.8,.12); }catch(e){} }\n  else { callMargGatti(f,o); } }\nfunction stepMarg(f,o){ const M=f.mgsup; if(!M) return; M.t++; const t=o||M.tgt;\n  if(M.evo){ if(M.t<24) return; if(M.t===24){ G.shake=Math.max(G.shake,14); }\n    M.wx+=M.dir*MARGSU.wv;\n    if(t&&!M.hit&&t.state!=='ko'&&(t.x-M.wx)*M.dir<90&&(t.x-M.wx)*M.dir>-40){ M.hit=1; if(t.y>GROUND-95){ G.shake=Math.max(G.shake,18); hit(f,t,MARGSU.dmgE,14,46,{sup:true,heavy:true,launch:true,dirx:M.dir,y:t.y-80}); if(t.state==='hit') floatText('RRROAR!',t.x,t.y-230,'#ffffff',30,60); } }\n    if(M.t>24+70||M.wx<-260||M.wx>W+260) f.mgsup=null; return; }\n  if(M.t<4) return; if(!M.drop){ M.cx+=M.dir*MARGSU.vel; const tx=t?t.x:f.x+M.dir*300; if((M.cx-tx)*M.dir>-10){ M.drop={x:M.cx,y:GROUND-330,vy:0}; } }\n  else { M.cx+=M.dir*MARGSU.vel; const B=M.drop; if(!B.done){ B.vy+=0.9; B.y+=B.vy; if(t) B.x+=Math.max(-3,Math.min(3,t.x-B.x));\n      if(B.y>GROUND-40){ B.done=1; B.t=0; G.shake=Math.max(G.shake,12); if(t&&!M.hit&&t.state!=='ko'&&Math.abs(t.x-B.x)<MARGSU.rng){ M.hit=1; hit(f,t,M.sp?13:MARGSU.dmg,14,46,{sup:!M.sp,heavy:true,launch:true,dirx:M.dir,y:t.y-70}); if(t.state==='hit') floatText('CONSEGNA!',t.x,t.y-230,'#ffffff',30,60); } else floatText('Mancato!',B.x,GROUND-120,'#ffffff',16,40,'balloon'); } }\n    else { B.t++; } }\n  if(M.drop&&M.drop.done&&M.drop.t>40&&(M.cx>W+300||M.cx<-300)) f.mgsup=null; else if(M.t>240) f.mgsup=null; }\nfunction drawMarg(F){ if(!F||!F.def||F.def.spriteKey!=='marghera') return; const M=F.mgsup; if(!M) return; ctx.save(); ctx.imageSmoothingEnabled=false;\n  if(M.evo){ const ti=margImg('tigre'); if(ti){ const a=Math.min(1,M.t/18)*Math.max(0,Math.min(1,(94-M.t)/14)); const x=M.t<24?F.x-M.dir*30:M.wx, y=GROUND-6-(M.t<24?0:Math.sin(Math.min(1,(M.t-24)/40)*Math.PI)*40); const s=M.t<24?0.8+0.25*M.t/24:1.05; ctx.globalAlpha=0.95*a; ctx.translate(x,y); ctx.scale(M.dir,1); ctx.drawImage(ti,-ti.width*s*0.6,-ti.height*s,ti.width*s,ti.height*s); ctx.setTransform(1,0,0,1,0,0); ctx.globalAlpha=1; }\n    ctx.restore(); return; }\n  if(M.t>=4){ const ci=margImg(((M.t>>3)%2)?'cicogna2':'cicogna1')||margImg('cicogna1'); if(ci){ const s=1; ctx.translate(M.cx,GROUND-340+Math.sin(M.t*0.2)*6); ctx.scale(M.dir,1); ctx.drawImage(ci,-ci.width*s/2,-ci.height*s/2,ci.width*s,ci.height*s); ctx.setTransform(1,0,0,1,0,0); } }\n  const B=M.drop; if(B){ const fa=margImg('fagotto'); if(fa&&!(B.done&&B.t>40)){ const s=0.9; ctx.globalAlpha=B.done?Math.max(0,1-B.t/40):1; ctx.drawImage(fa,B.x-fa.width*s/2,B.y-fa.height*s/2,fa.width*s,fa.height*s); ctx.globalAlpha=1; }\n    if(B.done&&B.t<18){ const bo=margImg('boom'); if(bo){ const s=0.6+B.t*0.03; ctx.globalAlpha=1-B.t/18; ctx.drawImage(bo,B.x-bo.width*s/2,GROUND-20-bo.height*s/2,bo.width*s,bo.height*s); ctx.globalAlpha=1; } } }\n  ctx.restore(); }\n";